{'stdout': '## 6. Case packet — input cho analyst

Tầng deterministic dựng hồ sơ; **agent không bao giờ đọc Parquet thô**:

```yaml
task:
  map_features: {narrowest_passage_m: 0.68, obstacle_density: 0.21, topology: corridor_with_side_aisles}
  robot: {width_m: 0.52, inflation_radius_m: 0.11}
candidates:            # FULL STACK, không chỉ tên thuật toán
  A: {global_planner: astar,   local_controller: dwa, params: …, providers: …}
  B: {global_planner: rrtstar, local_controller: dwa, p

/** The five outcomes, as behaviour.
 *
 * The one that matters: three of them have no paired comparison, and a
 * panel that draws a waterfall for them is decomposing a difference
 * nobody computed.
 */

import { describe, expect, it } from "vitest";

import type { DecisionRun } from "@/lib/decisions";
import { panelPlan, runOutcome } from "@/lib/explainPanel";

function run(overrides: Record<string, unknown>): DecisionRun {
  return {
    ranked: true,
    card: { status: "CLEAR_RECOMMENDATION" },
    report: { sample: {}, candidates: [] },
    ...overrides,
  } as unknown as DecisionRun;
}

describe("what the panel may show", () => {
  it("shows the comparison only where one exists", () => {
    for (const outcome of ["no_survivors", "gate_only"] as const) {
      const plan =
        outcome === "gate_only"
          ? panelPlan(run({ ranked: false, card: null, report: { gate_only_deployment: "x", sample: {} } }))
          : panelPlan(run({ ranked: false, card: null, report: { sample: {} } }));

      expect(plan.outcome).toBe(outcome);
      expect(plan.showWaterfall).toBe(false);
      expect(plan.showClaims).toBe(false);
      expect(plan.showExemplars).toBe(false);
      // The gate table is the entire content of these two.
      expect(plan.showGateTable).toBe(true);
    }
  });

  it("keeps an interrupted run's evidence and its caveat", () => {
    const plan = panelPlan(
      run({ ranked: false, card: null, report: { sample: { interrupted: true } } }),
    );

    expect(plan.outcome).toBe("interrupted");
    expect(plan.showWaterfall).toBe(true);
    expect(plan.caveatKeys).toContain("explain.caveat.fewerEpisodes");
  });

  it("says a near-equivalent result was decided by the tie-break", () => {
    const plan = panelPlan(run({ card: { status: "NEAR_EQUIVALENT" } }));

    expect(plan.outcome).toBe("near_equivalent");
    expect(plan.caveatKeys).toContain("explain.caveat.insideTheNoise");
    expect(plan.caveatKeys).toContain("explain.caveat.tieBreak");
  });

  it("leads with not-finishing even when nobody survived either", () => {
    const outcome = runOutcome(
      run({ ranked: false, card: null, report: { sample: { interrupted: true }, gate_only_deployment: "x" } }),
    );
    expect(outcome).toBe("interrupted");
  });

  it("every outcome names a headline", () => {
    const plans = [
      panelPlan(run({})),
      panelPlan(run({ card: { status: "NEAR_EQUIVALENT" } })),
      panelPlan(run({ ranked: false, card: null, report: { sample: {} } })),
    ];
    expect(plans.every((plan) => plan.headlineKey.startsWith("explain.headline."))).toBe(true);
  });
});

/** Which parts of the explanation surface a run may show.
 *
 * A port of `planbench_explanation.panel`, kept deliberately thin: the
 * *decision* lives on the platform, this reads it. The five outcomes and
 * their flags are duplicated here only because the page has to render
 * before any explanation endpoint answers, and a page that guesses
 * would guess differently from the server.
 *
 * The rule the duplication protects: three of the five outcomes have no
 * paired comparison, so there is no Î”U to decompose, nobody to compare
 * episodes between, and no "why A won" to claim. Drawing any of those
 * would answer a question the run never asked.
 */

import type { DecisionRun } from "./decisions";
import { noCardReason } from "./decisions";

export type RunOutcome =
  | "clear"
  | "near_equivalent"
  | "no_survivors"
  | "gate_only"
  | "interrupted";

export interface PanelPlan {
  outcome: RunOutcome;
  showWaterfall: boolean;
  showClaims: boolean;
  showExemplars: boolean;
  showGateTable: boolean;
  headlineKey: string;
  /** Caveats that belong beside the numbers, not in a footnote. */
  caveatKeys: string[];
}

const PLANS: Record<RunOutcome, PanelPlan> = {
  clear: {
    outcome: "clear",
    showWaterfall: true,
    showClaims: true,
    showExemplars: true,
    showGateTable: true,
    headlineKey: "explain.headline.clear",
    caveatKeys: ["explain.caveat.scope"],
  },
  near_equivalent: {
    outcome: "near_equivalent",
    showWaterfall: true,
    showClaims: true,
    showExemplars: true,
    showGateTable: true,
    headlineKey: "explain.headline.nearEquivalent",
    caveatKeys: [
      "explain.caveat.insideTheNoise",
      "explain.caveat.tieBreak",
      "explain.caveat.scope",
    ],
  },
  no_survivors: {
    outcome: "no_survivors",
    showWaterfall: false,
    showClaims: false,
    showExemplars: false,
    showGateTable: true,
    headlineKey: "explain.headline.noSurvivors",
    caveatKeys: ["explain.caveat.registerABetterCandidate"],
  },
  gate_only: {
    outcome: "gate_only",
    showWaterfall: false,
    showClaims: false,
    showExemplars: false,
    showGateTable: true,
    headlineKey: "explain.headline.gateOnly",
    caveatKeys: ["explain.caveat.deploymentCannotRank"],
  },
  interrupted: {
    outcome: "interrupted",
    showWaterfall: true,
    showClaims: true,
    showExemplars: true,
    showGateTable: true,
    headlineKey: "explain.headline.interrupted",
    caveatKeys: ["explain.caveat.fewerEpisodes", "explain.caveat.scope"],
  },
};

/** Which of the five this run is.
 *
 * `interrupted` leads among the no-card cases: a run that stopped early
 * may *also* have had nobody survive, and "we did not finish" is the
 * fact that makes the second one uninterpretable.
 */
export function runOutcome(run: DecisionRun): RunOutcome {
  const reason = noCardReason(run);
  if (reason === "interrupted") return "interrupted";
  if (reason === "gate_only") return "gate_only";
  if (reason === "no_survivors") return "no_survivors";
  if (run.report?.sample?.interrupted) return "interrupted";
  const status = (run.card as { status?: string } | null)?.status;
  return status === "NEAR_EQUIVALENT" ? "near_equivalent" : "clear";
}

export function panelPlan(run: DecisionRun): PanelPlan {
  return PLANS[runOutcome(run)];
}

